<section class="appSection" id="updates"><div class="appSectionHeading"><div><span class="sectionKicker">YOUR ACCOUNT UPDATES</span><h2>Recent updates</h2><p>See the latest progress from your solar team.</p></div><span class="sectionCounter"><?= count($activity) ?> UPDATES</span></div><?php if (!$activity): ?><div class="emptyState compactEmpty"><strong>No updates yet.</strong><p>Quote, project, and support updates from the team will appear here.</p></div><?php else: ?><div class="activityList"><?php foreach ($activity as $event): ?><article class="activityItem"><span class="activityDot"></span><div><strong><?= esc($event['description']) ?></strong><p><?= esc(ucfirst($event['entity_type'])) ?> update</p></div><time datetime="<?= esc(date(DATE_ATOM, strtotime($event['created_at']))) ?>"><?= esc(date('M j, Y · g:i A', strtotime($event['created_at']))) ?></time></article><?php endforeach ?></div><?php endif ?></section>
